from html.parser import HTMLParser
from pathlib import Path
import urllib.request

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hidden = 0
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.hidden -= 1
    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

def visible(html):
    parser = VisibleText()
    parser.feed(html)
    return ' '.join(' '.join(parser.parts).split())

shell = Path('.next/server/app/index.html').read_text()
assert '<h1>Workspace</h1>' in shell
assert 'Loading your member, team, and region…' in shell
assert '<p>12<"'!-- --> active projects</p>'"' in shell
assert 'Welcome,' not in shell
print('Prerendered shell has heading, shared total, and member fallback; no member data')

for name, team, region, other in [('Avery', 'Platform', 'eu-west', 'Blair'), ('Blair', 'Design', 'ap-south', 'Avery')]:
    req = urllib.request.Request('http://localhost:3100/', headers={'Cookie': f'member={name}; team={team}', 'x-region': region})
    with urllib.request.urlopen(req) as res:
        body = visible(res.read().decode())
        assert res.status == 200
    for expected in [f'Welcome, {name}', f'Team: {team}', f'Region: {region}', '12 active projects']:
        assert expected in body, (expected, body)
    assert other not in body
    print(f'{name}: personal details and shared total verified')
